var PAGES = [
  {key:"title", art:"0-00", run:"", html:
    '<div class="title-page"><svg class="pen" viewBox="0 0 260 24" aria-hidden="true" fill="none"><path d="M2 15c22-9 38 4 60-2s30-10 52-4 28 9 52 3 34-9 52-5 22 6 40 2" stroke="currentColor" stroke-width="2.6" stroke-linecap="round"/><circle cx="252" cy="11" r="2.4" fill="currentColor"/></svg>'+
    '<h2 class="h" tabindex="-1" style="font-size:2.3em;line-height:1.08;margin:0 0 .4rem">Not a Storyteller, As a Rule</h2><p class="sub">The stories of Lew Etcoff, in his own words</p>'+
    '<blockquote class="pull small"><p>\u201cI\u2019m not a storyteller, as a rule.\u201d</p></blockquote><p class="frame-line">A modest man who turns out to have plenty of stories.</p>'+
    '<p class="intro clip" data-clip="0-00">Every week for a year, Lew answered a question about his life. These are some of his answers. Read them, listen to them, or both.</p></div>'},
  {key:"ch1", art:"house", run:"", html:
    '<div class="opener"><p class="label">Chapter 1</p><h2 class="h" tabindex="-1">Isabell Circle</h2><blockquote class="pull"><p>\u201cAs you can tell, we had a super time as children.\u201d</p></blockquote><p class="frame-line">The kid who invented games, and the friends he still talks to every Monday.</p></div>'},
  {key:"p1", title:"Randolph, Massachusetts", clips:[
    {id:"1-01", art:"1-01", text:"When I look back on my life, I believe that I was happiest during elementary school, when I had a lot of same-age friends to play with on Isabell Circle in Randolph, Mass."}]},
  {key:"p2", title:"The game in the woods", clips:[
    {id:"1-02", art:"1-02", text:"We had a mile or so of woods just behind my house, and my friends and I made up \u201cthe game in the woods.\u201d Our invention. A mixture of hide and seek and tag. One team hid anywhere within a quarter mile of \u201cGools,\u201d a huge rock left from the Ice Age, I suspect. The other team had to tag you before you could run back and jump onto the rock."},
    {id:"1-03", art:"1-03", push:true, text:"You could climb a tree in the pine forest. You could lure the defenders into the thorn bushes, where they'd get stuck while you ran to the rock. It was a very fun and creative game."}]},
  {key:"p3", title:"The rocky ball field", clips:[
    {id:"1-04", art:"1-04", text:"One summer, we built our own baseball field. It was very rocky and uneven. First base had a huge rock behind it. In short right field were a bunch of immovable boulders, one of which I tripped over while backpedaling to catch a pop-up, and I broke my left arm."},
    {id:"1-05", art:"1-05", text:"I got to wear a cast for over a month. Everyone signed it. I used the time to learn how to shoot a basketball and throw a baseball with my right hand."}]},
  {key:"p4", title:"Snowball", clips:[
    {id:"1-06", art:"1-06", text:"I'd take my pet cat, Snowball, for a walk to the Carlinos' basketball court two streets over. The cat hung around while I practiced, and walked home with me."}]},
  {key:"p5", title:"After dark, after the rain", clips:[
    {id:"1-07", art:"1-07", text:"At night, we played hide and seek. It was great fun scaring the guy who was \u201cit\u201d when he came near you but couldn't see you in the dark."},
    {id:"1-08", art:"1-08", text:"After it rained, we'd ride our bikes through the puddles, over and over in a circle, until the circle was completely wet with no dry spots. Just for the fun of it."}]},
  {key:"p6", title:"The treehouse", clips:[
    {id:"1-09", art:"1-09", text:"One of our treehouses had wallpaper, tar paper, and roof shingles. It was a two-story house."}],
    after:'<aside class="note" aria-label="Another of his answers"><p class="q"><span class="k">Asked:</span> What advice do you wish you had taken from your parents?</p><p class="a">\u201cWatch out for protruding nails when you build tree huts!\u201d</p></aside>'},
  {key:"p7", title:"The boys", clips:[
    {id:"1-10", art:"1-11", text:"As you can tell, we had a super time as children."},
    {id:"1-11", art:"1-11", text:"I loved my neighborhood and the boys I made friends with, all of whom I still talk with every Monday at 10 a.m. Pacific, 1 p.m. Eastern."}]},
  {key:"answers", art:"end", run:"Isabell Circle", html:'<h2 class="h" tabindex="-1">Read his full answers</h2><p style="color:var(--muted);font-size:.88em;margin:0 0 .8rem">This chapter draws on two of his answers. Here they are in full, with typos lightly corrected.</p>__FULLANS__'},
  {key:"ch2", art:"2-00", run:"", html:
    '<div class="opener"><p class="label">Chapter 2</p><h2 class="h" tabindex="-1">Where He Came From</h2><blockquote class="pull"><p>\u201cThe apple doesn\u2019t fall far from the tree, now does it?\u201d</p></blockquote><p class="frame-line">What he inherited from each parent, the good and the quirky.</p></div>'},
  {key:"q1", ch:"Chapter 2: Where He Came From", title:"His mother", clips:[
    {id:"2-01", art:"2-01", text:"My mother had an easy and warm smile, laughed a lot, was very loving, and always made a warm home for the family. She cleaned the floors on her hands and knees, cooked every meal for us, and worked full-time. She never gave up and always gave her very best. What I learned to copy from my mom was her hard work ethic, despite her worries and financial stresses."}]},
  {key:"q2", ch:"Chapter 2: Where He Came From", title:"Charlie", clips:[
    {id:"2-02", art:"2-02", text:"I have my dad's sense of humor and his easy social style with his customers and neighbors. Everyone loved Charlie. He was a big shot at the synagogue because he sang the hymn Yigdal with feeling that everyone loved\u2026 but me! I found it too schmaltzy. It embarrassed me, the way children are so easily embarrassed by their parents."},
    {id:"2-03", art:"2-03", text:"My father loved music, especially Jewish liturgical music, which became a part of me. My dad loved the Red Sox, Celtics, and Patriots. I do too."}]},
  {key:"q3", ch:"Chapter 2: Where He Came From", title:"Only the wins", clips:[
    {id:"2-04", art:"2-05", text:"I can't bear my team screwing up and losing. So I record games and only watch them if my team wins. Sometimes I won't watch them even if my team wins, if the game was close\u2026 too nerve-wracking. I love watching blowouts, where the Patriots win 50 to 6."},
    {id:"2-05", art:"2-05", push:true, text:"This may have started when my father sent me videotapes of only Celtics wins. He taped over the games they lost. Ha ha ha! The apple doesn't fall far from the tree, now does it?"}]},
  {key:"answers2", art:"2-06", run:"Where He Came From", html:'<h2 class="h" tabindex="-1">Read his full answers</h2><p style="color:var(--muted);font-size:.88em;margin:0 0 .8rem">This chapter draws on four of his answers. Two are shortened here; the rest are in full, with typos lightly corrected.</p>__FULLANS__', full:"CH2"},
  {key:"ch3", art:"3-00", run:"", html:
    '<div class="opener"><p class="label">Chapter 3</p><h2 class="h" tabindex="-1">The Hippie and the Singer</h2><blockquote class="pull"><p>\u201cWhat a trip!\u201d</p></blockquote><p class="frame-line">Finding his voice through music and humor.</p></div>'},
  {key:"r1", ch:"Chapter 3: The Hippie and the Singer", title:"College", clips:[
    {id:"3-01", art:"3-01", text:"Once I got to college, I conformed by becoming a hippie. Long hair, mustache, crummy beard, bell bottoms, and guitar playing. Being a hippie necessitated wearing a ponytail too, which I enjoyed."}]},
  {key:"r2", ch:"Chapter 3: The Hippie and the Singer", title:"Jerusalem", clips:[
    {id:"3-02", art:"3-02", text:"In 1971, I went to Israel for my junior year abroad at Hebrew University. My hippie look didn't make me any friends with Israelis, who gave me dirty looks on the buses."},
    {id:"3-03", art:"3-03", text:"But I became known as a funny singer and songwriter, chronicling our experiences as American students in Israel. My friend Steve and I played our goofy songs for the whole class. I also played at underground coffee shops around Jerusalem."}]},
  {key:"r3", ch:"Chapter 3: The Hippie and the Singer", title:"The Zamir Chorale", clips:[
    {id:"3-04", art:"3-04", text:"For five years, I sang in a chorus called the Zamir Chorale, every Thursday night at Boston University. In 1975, we went to Israel and learned to sing Beethoven's Ninth Symphony with the world-famous conductor Daniel Barenboim. We got to watch Leonard Bernstein conduct the Israel Philharmonic in Tel Aviv."},
    {id:"3-05", art:"3-05", push:true, text:"And we sang the fourth movement of the Ninth in Jerusalem, in Tel Aviv, and in Tiberias\u2026 in an open-air Roman amphitheater, at night. What a trip!"}]},
  {key:"r4", ch:"Chapter 3: The Hippie and the Singer", title:"Off to grad school", clips:[
    {id:"3-06", art:"3-06", text:"The hippie fad lasted till age 21, when my hair got shorter. No more scraggly beard. I was off to grad school, still a serious student."}]},
  {key:"answers3", art:"3-05", run:"The Hippie and the Singer", html:'<h2 class="h" tabindex="-1">Read his full answers</h2><p style="color:var(--muted);font-size:.88em;margin:0 0 .8rem">This chapter draws on two of his answers. Both are shortened here, with typos lightly corrected.</p>__FULLANS__', full:"CH3"},
  {key:"ch4", art:"4-00", run:"", html:
    '<div class="opener"><p class="label">Chapter 4</p><h2 class="h" tabindex="-1">The Bravest Thing</h2><blockquote class="pull"><p>\u201cIt wasn\u2019t easy or smooth. But I did it.\u201d</p></blockquote><p class="frame-line">Courage he had to choose, again and again.</p></div>'},
  {key:"b1", ch:"Chapter 4: The Bravest Thing", title:"Leaving Boston", clips:[
    {id:"4-01", art:"4-01b", text:"Undoubtedly, leaving family and friends and Boston to go out on my own to Toledo, Ohio, was the bravest thing I ever did. I had suffered separation anxiety as a child, and I forced myself to leave everybody I cared about and everything I knew in order to overcome that fear. I didn't know how to cook, do laundry, or anything else to live on my own. It wasn't easy or smooth. But I did it."}]},
  {key:"b2", ch:"Chapter 4: The Bravest Thing", title:"Toledo", clips:[
    {id:"4-02", art:"4-02", text:"In Toledo, I worked for the Jewish Welfare Federation. I got to lead a fundraising mission to Israel. You've seen the picture of me riding a camel."},
    {id:"4-03", art:"4-03", text:"Then, at age 27, while working full-time, I took an undergrad major in psychology at night. I memorized 700 vocabulary words for the GRE. I tried studying math\u2026 to no avail. I applied to about fifteen Ph.D. programs and got into one."}]},
  {key:"b3", ch:"Chapter 4: The Bravest Thing", title:"The Air Force", clips:[
    {id:"4-04", art:"4-04", text:"In my fourth year of grad school, I joined the U.S. Air Force. I never imagined joining the USAF, but I did, and I enjoyed my time there."}]},
  {key:"b4", ch:"Chapter 4: The Bravest Thing", title:"Standing up", clips:[
    {id:"4-05", art:"4-05", text:"It was years and years later, when Mom and I were at a concert, that my pride in being a veteran dawned on me. At the beginning of the event, the MC asked everyone who had served their country to stand. I reluctantly stood, and so did a few hundred others. And I recall feeling very good that the audience gave us a hand."},
    {id:"4-06", art:"4-01", text:"All of these decisions were made possible by the self-confidence I gained leaving Boston on my own."}]},
  {key:"answers4", art:"4-07", run:"The Bravest Thing", html:'<h2 class="h" tabindex="-1">Read his full answers</h2><p style="color:var(--muted);font-size:.88em;margin:0 0 .8rem">This chapter draws on four of his answers. Three are shortened here; one is in full. Typos lightly corrected.</p>__FULLANS__', full:"CH4"},
  {key:"ch5", art:"5-00", run:"", html:
    '<div class="opener"><p class="label">Chapter 5</p><h2 class="h" tabindex="-1">The Helper</h2><blockquote class="pull"><p>\u201cI always gave everything I had to every patient I saw.\u201d</p></blockquote><p class="frame-line">A career spent helping kids.</p></div>'},
  {key:"h1", ch:"Chapter 5: The Helper", title:"Las Vegas", clips:[
    {id:"5-01", art:"5-01", text:"I never imagined living my life in Las Vegas, but it turned out to be a great place for me to start my professional career."}]},
  {key:"h1b", ch:"Chapter 5: The Helper", title:"Helping children", clips:[
    {id:"5-02", art:"5-02", text:"I chose to become a psychologist to help children overcome their learning disabilities and emotional struggles. When I noticed how my expertise changed a child's life for the good, I found my life more meaningful. I always gave everything I had to every patient I saw."}]},
  {key:"h2", ch:"Chapter 5: The Helper", title:"Twenty-five students", clips:[
    {id:"5-03", art:"5-03", text:"I voluntarily trained 25 psychology doctoral students, without compensation. Many of them went on to do the very things I helped them learn. I got a kick out of it, I'll admit."}]},
  {key:"h3", ch:"Chapter 5: The Helper", title:"The award", clips:[
    {id:"5-04", art:"5-04", text:"In 2020, I won the James Mikawa Leadership Award from the Nevada Psychological Association, for my many years evaluating children and teens, and my work with attorneys and the courts. This award made me feel very, very good."}]},
  {key:"answers5", art:"5-05", run:"The Helper", html:'<h2 class="h" tabindex="-1">Read his full answers</h2><p style="color:var(--muted);font-size:.88em;margin:0 0 .8rem">This chapter draws on four of his answers. One is shortened here; the rest are in full, with typos lightly corrected.</p>__FULLANS__', full:"CH5"},
  {key:"ch6", art:"6-op", run:"", html:
    '<div class="opener"><p class="label">Chapter 6</p><h2 class="h" tabindex="-1">Dad</h2><blockquote class="pull"><p>\u201cI loved being a dad.\u201d</p></blockquote><p class="frame-line">The fun, gentle parent. Mom ran the rules.</p></div>'},
  {key:"d1", ch:"Chapter 6: Dad", title:"Mom", clips:[
    {id:"6-00", art:"6-00", text:"I am very, very fortunate to have married such a wonderful, loving woman. She is my best friend. We get along so well, and she enriches my life."}]},
  {key:"d2", ch:"Chapter 6: Dad", title:"Jennifer", clips:[
    {id:"6-01", art:"6-01", text:"When Jennifer was born and I saw how perfect she looked, I was relieved and amazed and thrilled. I became a great poop diaper changer, a skill I was very proud of! I loved being a dad."}]},
  {key:"d3", ch:"Chapter 6: Dad", title:"Rules and regulations", clips:[
    {id:"6-02", art:"6-02", text:"I intentionally did not yell at you guys. I always tried to do whatever you wanted me to do with you, even if I was very busy. I left the rules and regulations to Mom, because I'm not by nature an organized, rule-following person."},
    {id:"6-02b", art:"6-02b", text:"Mom is the wisest person. This is both good and bad. Her logic is very helpful. But sometimes it is frustrating too. You know what I mean? But Mom can figure out the best way to get things accomplished, and she is worth listening to."}]},
  {key:"d4", ch:"Chapter 6: Dad", title:"Music on Mojave", clips:[
    {id:"6-03", art:"6-03", text:"I remember music times in the house on Mojave, as I played my favorite Beatles songs and taught you all of them. Thank God you both had good voices and could harmonize!"}]},
  {key:"d5", ch:"Chapter 6: Dad", title:"The backyard", clips:[
    {id:"6-04", art:"6-04", text:"Throwing a ball in the air in the backyard and calling out some amount of money. Whoever caught it won the money. When the price was high, I threw the ball so high you couldn't catch it."},
    {id:"6-05", art:"6-05", text:"Marco Polo in our backyard pool. I'd score your dives as if you were in the Olympics. Collecting sand crabs on our beach vacations."}]},
  {key:"d6", ch:"Chapter 6: Dad", title:"Recitals", clips:[
    {id:"6-06", art:"6-rec", text:"Jen, your dance recital, when you froze on stage and gave the other girls a very dirty look. That was a hoot."},
    {id:"6-07", art:"6-rec", text:"Allie, you playing the gong at a school recital… and knocking it over."}]},
  {key:"d7", ch:"Chapter 6: Dad", title:"Growing up", clips:[
    {id:"6-08", art:"6-grow", text:"Jen, the ride back from U of A, when we sang Beatles songs for hours."},
    {id:"6-09", art:"6-grow", text:"Allie, carrying you off the soccer field when you fractured your ankle, and me trying to comfort you."},
    {id:"6-10", art:"6-grow", text:"And Allie on a roller derby team in Reno. Frightened the crap out of Mom and me."}]},
  {key:"d8", ch:"Chapter 6: Dad", title:"Lake Mead", clips:[
    {id:"6-11", art:"6-11", text:"One of my very favorite pranks: I chaperoned Allie and her girlfriends on a camping trip at Lake Mead. Close to midnight, I snuck out of the van, collected rocks, and one by one, threw them at the tent. After about the third rock, you all became a little frightened. I faked sleeping when you came out to investigate. Then I threw another rock, and you all went bananas. I had to stifle how hard I was laughing. When I thought you'd had enough, I let you know it was me!"}]},
  {key:"d9", ch:"Chapter 6: Dad", title:"Unconditional love", clips:[
    {id:"6-12", art:"6-12", text:"What I hope I gave you as you were growing up, and still give you today, is my unconditional love."}]},
  {key:"answers6", art:"6-end", run:"Dad", html:'<h2 class="h" tabindex="-1">Read his full answers</h2><p style="color:var(--muted);font-size:.88em;margin:0 0 .8rem">This chapter draws on six of his answers. Three are shortened here; the rest are in full, with typos lightly corrected.</p>__FULLANS__', full:"CH6"},
  {key:"ch7", art:"7-op", run:"", html:
    '<div class="opener"><p class="label">Chapter 7</p><h2 class="h" tabindex="-1">Papa</h2><blockquote class="pull"><p>\u201cI am blessed to be their playmate, though a whole lot older.\u201d</p></blockquote><p class="frame-line">Becoming the grandfather he never had.</p></div>'},
  {key:"g1", ch:"Chapter 7: Papa", title:"His grandfather", clips:[
    {id:"7-01", art:"7-01", text:"My grandfather wasn't involved with his grandchildren. He didn't play with me or do anything to get to know me. So I make sure that my grandkids will have a lot more fond memories of me."}]},
  {key:"g2", ch:"Chapter 7: Papa", title:"Three grandsons", clips:[
    {id:"7-02", art:"7-02", text:"I am blessed to have three terrific grandsons who adore me as I adore them. I am blessed to be their playmate, though a whole lot older. Fortunately, they don't yet realize that I'm not a kid like them."}]},
  {key:"g3", ch:"Chapter 7: Papa", title:"Goofy games", clips:[
    {id:"7-03", art:"7-03", text:"Throwing coins into the hot tub is a winner for the boys. They love diving for the coins and keeping them in their piggy banks. Hiding money in different rooms of the house. Dropping magnetic darts onto the dartboard instead of throwing them. Flashlights at night, as a backyard adventure."}]},
  {key:"g4", ch:"Chapter 7: Papa", title:"Awe in the everyday", clips:[
    {id:"7-04", art:"7-04", text:"When I take my grandsons on walks, I show them what to pay attention to… a tree, a flower, a dog, sticks, the sky, the moon and the stars. I try to make every moment a sensory adventure. I want them to find awe in the everyday."}]},
  {key:"g5", ch:"Chapter 7: Papa", title:"Mimi and Papa", clips:[
    {id:"7-06", art:"7-06", text:"When the boys tell me they don't want me to leave, that they love Mimi and Papa, that they want a sleepover, a hike, or to play the goofy games I invent for them… I forget my aches and pains in those moments, and feel wonderful."}]},
  {key:"answers7", art:"7-end", run:"Papa", html:'<h2 class="h" tabindex="-1">Read his full answers</h2><p style="color:var(--muted);font-size:.88em;margin:0 0 .8rem">This chapter draws on four of his answers. Two are shortened here; the rest are in full, with typos lightly corrected.</p>__FULLANS__', full:"CH7"},
  {key:"ch8", art:"8-op", run:"", html:
    '<div class="opener"><p class="label">Chapter 8</p><h2 class="h" tabindex="-1">A Few of His Favorite Things</h2><blockquote class="pull"><p>\u201cThese are a few of my favorite things.\u201d</p></blockquote><p class="frame-line">Small pleasures, big enthusiasm.</p></div>'},
  {key:"f1", ch:"Chapter 8: A Few of His Favorite Things", title:"Pens and ink", clips:[
    {id:"8-01", art:"8-01", text:"Fountain pens. My favorites are Pelikans, of which I own eight at last count. Japanese inks: ama-iro and kon-peki. Good writing paper. Good coffee. Potato chips."}]},
  {key:"f2", ch:"Chapter 8: A Few of His Favorite Things", title:"Magnets!", clips:[
    {id:"8-02", art:"8-02", text:"Magnets! I play with them all the time and never tire of the force and resistance."},
    {id:"8-03", art:"8-03", text:"Binoculars. My guitars. Thunderstorms. The Tour de France. British crime shows. Tuna sandwiches, all the time. Hamburgers and fries. Chocolate. Gum. Wet wipes! Ha ha."}]},
  {key:"f3", ch:"Chapter 8: A Few of His Favorite Things", title:"The Lotus, the trike, and Alexa", clips:[
    {id:"8-04", art:"8-04", text:"I loved my Lotus Elise convertible. An eye-turner and a blast to drive. My trike. My iPad. I can't live without it. Alexa! What an invention!"}]},
  {key:"f4", ch:"Chapter 8: A Few of His Favorite Things", title:"The people", clips:[
    {id:"8-05", art:"8-05", text:"My dog. My cats. My old friends from childhood. My wonderful, supportive, and smart wife. Seeing how much my three grandchildren love me. Being very proud of my daughters."},
    {id:"8-06", art:"8-05", text:"These are a few of my favorite things, as the old song goes."}]},
  {key:"answers8", art:"8-end", run:"A Few of His Favorite Things", html:'<h2 class="h" tabindex="-1">Read his full answers</h2><p style="color:var(--muted);font-size:.88em;margin:0 0 .8rem">This chapter draws on two of his answers. One is shortened here; the other is in full. Typos lightly corrected.</p><div class="more-below">__FULLANS__</div>', full:"CH8"},
  {key:"ch9", art:"9-01", run:"", html:
    '<div class="opener"><p class="label">Chapter 9</p><h2 class="h" tabindex="-1">What He\u2019d Tell You</h2><blockquote class="pull"><p>\u201cPause as often as possible to take in that beauty.\u201d</p></blockquote><p class="frame-line">What he\u2019d want you to carry with you.</p></div>'},
  {key:"w1", ch:"Chapter 9: What He'd Tell You", title:"The meaning of life", clips:[
    {id:"9-01", art:"9-01b", text:"I don't think there is a one-size-fits-all meaning in life. Each person determines their own. What is common to us all? To make the best out of our unique circumstances. To realize that there is beauty in the natural world around us all. Pause as often as possible to take in that beauty… the sky, the breeze, the animals, the trees, the roofs over our heads, and the people who love us."}]},
  {key:"w2", ch:"Chapter 9: What He'd Tell You", title:"For the boys", clips:[
    {id:"9-02", art:"9-02", text:"Whether my great-grandchildren or my wonderful grandsons, here is what comes to mind."},
    {id:"9-03", art:"9-02", text:"Forgive yourself for your errors and flaws. Treat everyone the way you'd wish to be treated. Be curious about the wonderful natural world surrounding you. Use binoculars to see animals, especially birds and insects, as they do their thing. Be a good friend, and make friends for life. Get a dog and a cat."}]},
  {key:"w3", ch:"Chapter 9: What He'd Tell You", title:"Reach for the sky", clips:[
    {id:"9-04", art:"9-04", text:"Appreciate what you have, rather than long for what you don't have. Learn to play a musical instrument, and sing a lot. Apologize when you screw up. Learn how to play with children. Have a sense of humor. Laugh. Reach for the sky, and dream big dreams."}]},
  {key:"w4", ch:"Chapter 9: What He'd Tell You", title:"Papa loves you", clips:[
    {id:"9-05", art:"9-05", text:"And remember that Papa loves you very much."}],
    after:"<aside class=\"note\" aria-label=\"Another of his answers\"><p class=\"q\"><span class=\"k\">Asked:</span> What would you consider your motto?</p><p class=\"a\">“Be kind, for everyone you meet is fighting a hard battle.”</p></aside>"},
  {key:"answers9", art:"9-end", run:"What He\u2019d Tell You", html:'<h2 class="h" tabindex="-1">Read his full answers</h2><p style="color:var(--muted);font-size:.88em;margin:0 0 .8rem">This chapter draws on three of his answers, all in full, with typos lightly corrected.</p>__FULLANS__', full:"CH9"},
  {key:"ch10", art:"bday", run:"", html:'<div class="opener" style="align-items:flex-start"><h2 class="h" tabindex="-1" style="font-family:var(--hand);font-weight:600;color:var(--pen);font-size:3em;line-height:1.05">Happy 75th,<br>Dad and Papa.</h2><p class="frame-line">With love, from all of us.</p></div>'}
];
